6	)
7	
8	// A damaged event key -- invalid UTF-8 bytes or a \u escape with an unpaired
9	// or mispaired surrogate -- must be a fatal input error carrying the physical
10	// line number, never silently repaired to U+FFFD and counted.
11	
12	func TestAggregateDamagedKeyIsFatal(t *testing.T) {
13		cases := []struct {
14			name      string
15			key       string // raw JSON string literal, quotes included
16			wantInMsg string
17		}{
18			{"invalid utf-8 byte", "\"a\xffb\"", "UTF-8"},
19			{"truncated utf-8 sequence", "\"\xe6\xb8\"", "UTF-8"},
20			{"lone high surrogate", `"\uD800"`, "surrogate"},
21			{"lone low surrogate", `"\uDC00"`, "surrogate"},
22			{"high surrogate then text", `"\uD800x"`, "surrogate"},
23			{"high surrogate then high surrogate", `"\uD800\uD800"`, "surrogate"},
24			{"high surrogate then non-surrogate escape", `"\uD800A"`, "surrogate"},
25			{"low surrogate after valid pair", `"😀\uDC00"`, "surrogate"},
26		}
27		for _, tc := range cases {
28			t.Run(tc.name, func(t *testing.T) {
29				input := `{"type":"event","key":` + tc.key + `,"time":1,"value":1}` + "\n"
30				stdout, stderr, err := runAggregate(t, input, 1000)
31				if err == nil {
32					t.Fatal("expected error, got nil")
33				}
34				inputErr, ok := err.(*InputError)
35				if !ok {
36					t.Fatalf("expected *InputError, got %T: %v", err, err)
37				}
38				if inputErr.Line != 1 {
39					t.Errorf("line = %d, want 1", inputErr.Line)
40				}
41				if !strings.Contains(inputErr.Reason, `"key"`) {
42					t.Errorf("reason = %q, want it to name the key field", inputErr.Reason)
43				}
44				if !strings.Contains(inputErr.Reason, tc.wantInMsg) {
45					t.Errorf("reason = %q, want substring %q", inputErr.Reason, tc.wantInMsg)
46				}
47				if stdout != "" {
48					t.Errorf("damaged key must not produce output, got %q", stdout)
49				}
50				if stderr != "" {
51					t.Errorf("damaged key must not produce a late notice, got %q", stderr)
52				}
53			})
54		}
55	}
56	
57	// The damaged key is fatal even when the event time is below the current
58	// watermark: it must not be downgraded to a late-event notice.
59	func TestAggregateDamagedKeyBelowWatermarkIsFatalNotLate(t *testing.T) {
60		input := strings.Join([]string{
61			`{"type":"watermark","time":1000}`,
62			``, // line 2 blank, still counted
63			`{"type":"event","key":"\uD800","time":500,"value":1}`,
